class Solution:
    def separateSquares(self, squares):
        xs = sorted({x for x, y, l in squares} | {x + l for x, y, l in squares})
        idx = {v: i for i, v in enumerate(xs)}
        m = len(xs) - 1            # number of elementary x-intervals

        events = []
        for x, y, l in squares:
            a, b = idx[x], idx[x + l]
            events.append((y, 1, a, b))
            events.append((y + l, -1, a, b))
        events.sort()

        cnt = [0] * (4 * m)
        cov = [0] * (4 * m)        # covered length inside each segment tree node

        def update(node, lo, hi, a, b, v):
            if b <= lo or hi <= a:
                return
            if a <= lo and hi <= b:
                cnt[node] += v
            else:
                mid = (lo + hi) // 2
                update(2 * node, lo, mid, a, b, v)
                update(2 * node + 1, mid, hi, a, b, v)
            if cnt[node] > 0:
                cov[node] = xs[hi] - xs[lo]
            elif hi - lo == 1:
                cov[node] = 0
            else:
                cov[node] = cov[2 * node] + cov[2 * node + 1]

        slabs = []                 # (y_start, height, covered_width)
        prev = events[0][0]
        total = 0
        for y, v, a, b in events:
            if y > prev:
                slabs.append((prev, y - prev, cov[1]))
                total += cov[1] * (y - prev)
                prev = y
            update(1, 0, m, a, b, v)

        acc = 0
        for ys, h, w in slabs:
            if w > 0 and 2 * (acc + w * h) >= total:
                return ys + (total - 2 * acc) / (2 * w)
            acc += w * h
        return float(prev)
